PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS ROLLOUT_FILE_RULE (
    RULE_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    RULE_NAME TEXT NOT NULL UNIQUE,
    FILE_NAME_PATTERN TEXT NOT NULL,
    MATCH_TYPE TEXT NOT NULL DEFAULT 'GLOB'
        CHECK (MATCH_TYPE IN ('GLOB', 'REGEX', 'EXACT')),
    TARGET_DIRECTORY TEXT,
    DECISION TEXT NOT NULL DEFAULT 'AUTO'
        CHECK (DECISION IN ('AUTO', 'MANUAL', 'REJECT', 'IGNORE')),
    PRIORITY INTEGER NOT NULL DEFAULT 100,
    PRESERVE_RELATIVE_PATH INTEGER NOT NULL DEFAULT 0
        CHECK (PRESERVE_RELATIVE_PATH IN (0, 1)),
    ACTIVE_FLAG INTEGER NOT NULL DEFAULT 1
        CHECK (ACTIVE_FLAG IN (0, 1)),
    DESCRIPTION TEXT,
    CREATED_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS ROLLOUT_FILE_RULE_ACTION (
    RULE_ACTION_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    RULE_ID INTEGER NOT NULL,
    ACTION_ORDER INTEGER NOT NULL,
    ACTION_TYPE TEXT NOT NULL
        CHECK (ACTION_TYPE IN ('REPLACE', 'RUNMSQL', 'IMPORTSLDATA', 'LOADDATA', 'MBUILD')),
    COMMAND_TEMPLATE TEXT NOT NULL,
    ACTIVE_FLAG INTEGER NOT NULL DEFAULT 1
        CHECK (ACTIVE_FLAG IN (0, 1)),
    FOREIGN KEY (RULE_ID) REFERENCES ROLLOUT_FILE_RULE(RULE_ID) ON DELETE CASCADE,
    UNIQUE (RULE_ID, ACTION_ORDER)
);

CREATE INDEX IF NOT EXISTS IDX_ROLLOUT_RULE_MATCH
    ON ROLLOUT_FILE_RULE (ACTIVE_FLAG, PRIORITY, FILE_NAME_PATTERN);

CREATE INDEX IF NOT EXISTS IDX_ROLLOUT_ACTION_SEQUENCE
    ON ROLLOUT_FILE_RULE_ACTION (RULE_ID, ACTION_ORDER);

-- Placeholders used by COMMAND_TEMPLATE:
-- {package_file}     Relative file path inside the generated rollout.
-- {target_directory} Target relative to $LESDIR.
-- {file_name}        Basename of the uploaded file.
-- {csv_family}       CSV table/folder prefix, such as poldat.

-- Validation: identify exact duplicate patterns with different automatic targets.
SELECT FILE_NAME_PATTERN,
       PRIORITY,
       COUNT(DISTINCT TARGET_DIRECTORY) AS TARGET_COUNT,
       GROUP_CONCAT(TARGET_DIRECTORY, ' | ') AS TARGETS
FROM ROLLOUT_FILE_RULE
WHERE ACTIVE_FLAG = 1
  AND DECISION = 'AUTO'
GROUP BY FILE_NAME_PATTERN, PRIORITY
HAVING COUNT(DISTINCT TARGET_DIRECTORY) > 1;

-- Resolver rule: match using GLOB, then choose the lowest PRIORITY value.
-- If multiple rules tie at the winning priority, IMP must stop for manual review.
